import yaml
src = open('source.md').read()
body = src.split('---\n',3)[3] if src.count('---')>=3 else src
for f in ['intake/work-items.yaml','intake/questions.yaml']:
    d = yaml.safe_load(open(f))
    entries = d.get('items') or d.get('questions')
    for e in entries:
        if 'excerpts' in e:
            for ex in e['excerpts']:
                print(f, e['id'], repr(ex[:40]), ex in body)
        if e.get('question'):
            print(f, e['id'], 'q ok')
